import { builder } from './builder';
import './nodes';

builder.queryType({
  authScopes: { loggedIn: true },
  fields: (t) => ({
    serviceName: t.string({
      skipTypeScopes: true,
      resolve: () => 'Publishing API',
    }),
  }),
});

export const schema = builder.toSchema();

import SchemaBuilder from '@pothos/core';
import RelayPlugin from '@pothos/plugin-relay';
import ScopeAuthPlugin from '@pothos/plugin-scope-auth';

type Permission = 'readArticle' | 'editArticle';
type Context = { user: { id: string; permissions: Permission[] } | null };

export const builder = new SchemaBuilder<{
  Context: Context;
  AuthScopes: { loggedIn: boolean; permission: Permission };
}>({
  plugins: [ScopeAuthPlugin, RelayPlugin],
  relay: {
    nodeQueryOptions: {
      authScopes: { loggedIn: true },
    },
    nodesQueryOptions: {
      authScopes: { loggedIn: true },
    },
    nodeTypeOptions: {
      authScopes: { loggedIn: true },
    },
  },
  scopeAuth: {
    authScopes: (context) => ({
      loggedIn: !!context.user,
      permission: (permission) => context.user?.permissions.includes(permission) ?? false,
    }),
    unauthorizedError: () => new Error('Not authorized'),
  },
});

import { builder } from './builder';

type Article = { id: string; title: string };
const articles: Article[] = [{ id: '1', title: 'A field guide to GraphQL' }];

const ArticleNode = builder.objectRef<Article>('Article');

builder.node(ArticleNode, {
  id: { resolve: (article: Article) => article.id },
  loadOne: (id) => {
    return articles.find((article) => article.id === id) ?? null;
  },
  authScopes: {
    $any: {
      permission: 'readArticle',
      $granted: 'readFeaturedArticle',
    },
  },
  fields: (t) => ({
    title: t.exposeString('title'),
  }),
});

builder.queryField('featuredArticle', (t) =>
  t.field({
    type: ArticleNode,
    nullable: true,
    grantScopes: ['readFeaturedArticle'],
    resolve: () => {
      return articles[0];
    },
  }),
);

defaultQuery:
query PrivateNodePolicy {
  serviceName
  featuredArticle {
    title
  }
  node(id: "QXJ0aWNsZTox") {
    ... on Article {
      title
    }
  }
}

